"c": "<div class=\"line\" data-l=\"0\"><span class=\"kw\">int</span> <span class=\"fn\">binarySearch</span>(<span class=\"kw\">int</span> arr[], <span class=\"kw\">int</span> n, <span class=\"kw\">int</span> target) {</div><div class=\"line\" data-l=\"1\">    <span class=\"kw\">int</span> lo = <span class=\"num num2\">0</span>, hi = n - <span class=\"num num2\">1</span>;</div><div class=\"line\" data-l=\"2\">    <span class=\"kw\">while</span> (lo &lt;= hi) {</div><div class=\"line\" data-l=\"3\">        <span class=\"kw\">int</span> mid = lo + (hi - lo) / <span class=\"num num2\">2</span>;  <span class=\"cm\">// avoids overflow</span></div><div class=\"line\" data-l=\"4\">        <span class=\"kw\">if</span> (arr[mid] == target) <span class=\"kw\">return</span> mid;      <span class=\"cm\">// found it</span></div><div class=\"line\" data-l=\"5\">        <span class=\"kw\">else</span> <span class=\"kw\">if</span> (arr[mid] &lt; target) lo = mid + <span class=\"num num2\">1</span>; <span class=\"cm\">// drop left</span></div><div class=\"line\" data-l=\"6\">        <span class=\"kw\">else</span> hi = mid - <span class=\"num num2\">1</span>;                        <span class=\"cm\">// drop right</span></div><div class=\"line\" data-l=\"6\">    }</div><div class=\"line\" data-l=\"7\">    <span class=\"kw\">return</span> -<span class=\"num num2\">1</span>;             <span class=\"cm\">// not in the list</span></div><div class=\"line\" data-l=\"7\">}</div>",
