"c": "<div class=\"line\" data-l=\"0\"><span class=\"kw\">void</span> <span class=\"fn\">bubbleSort</span>(<span class=\"kw\">int</span> arr[], <span class=\"kw\">int</span> n) {</div><div class=\"line\" data-l=\"1\">    <span class=\"cm\">// a C array does not know its own size, so n comes in</span></div><div class=\"line\" data-l=\"2\">    <span class=\"kw\">for</span> (<span class=\"kw\">int</span> i = <span class=\"num num2\">0</span>; i &lt; n; i++) {</div><div class=\"line\" data-l=\"2\">        <span class=\"kw\">int</span> swapped = <span class=\"num num2\">0</span>;   <span class=\"cm\">// C has no bool before C99</span></div><div class=\"line\" data-l=\"3\">        <span class=\"kw\">for</span> (<span class=\"kw\">int</span> j = <span class=\"num num2\">0</span>; j &lt; n - i - <span class=\"num num2\">1</span>; j++) {</div><div class=\"line\" data-l=\"4\">            <span class=\"kw\">if</span> (arr[j] &gt; arr[j+<span class=\"num num2\">1</span>]) {</div><div class=\"line\" data-l=\"5\">                <span class=\"cm\">// C has no built-in swap - do it by hand</span></div><div class=\"line\" data-l=\"6\">                <span class=\"kw\">int</span> t = arr[j];</div><div class=\"line\" data-l=\"6\">                arr[j] = arr[j+<span class=\"num num2\">1</span>];</div><div class=\"line\" data-l=\"6\">                arr[j+<span class=\"num num2\">1</span>] = t;</div><div class=\"line\" data-l=\"6\">                swapped = <span class=\"num num2\">1</span>;</div><div class=\"line\" data-l=\"7\">            }</div><div class=\"line\" data-l=\"8\">        }</div><div class=\"line\" data-l=\"11\">        <span class=\"kw\">if</span> (!swapped) <span class=\"kw\">break</span>;  <span class=\"cm\">// a clean pass means sorted</span></div><div class=\"line\" data-l=\"9\">    }</div><div class=\"line\" data-l=\"10\">}</div>",
"cpp": "<div class=\"line\" data-l=\"\"><span class=\"kw\">#include</span> <span style=\"color:#a5d6ff\">&lt;vector&gt;</span></div><div class=\"line\" data-l=\"\"><span class=\"kw\">#include</span> <span style=\"color:#a5d6ff\">&lt;algorithm&gt;</span>       // gives you std::swap</div><div class=\"line\" data-l=\"\"><span class=\"kw\">using</span> <span class=\"kw\">namespace</span> std;</div><div class=\"line\" data-l=\"\">&nbsp;</div><div class=\"line\" data-l=\"0\"><span class=\"kw\">void</span> <span class=\"fn\">bubbleSort</span>(vector&lt;<span class=\"kw\">int</span>&gt;&amp; arr) {</div><div class=\"line\" data-l=\"1\">    <span class=\"kw\">int</span> n = arr.<span class=\"fn\">size</span>();    <span class=\"cm\">// a vector DOES know its size</span></div><div class=\"line\" data-l=\"2\">    <span class=\"kw\">for</span> (<span class=\"kw\">int</span> i = <span class=\"num num2\">0</span>; i &lt; n; i++) {</div><div class=\"line\" data-l=\"2\">        <span class=\"kw\">bool</span> swapped = <span class=\"kw\">false</span>;</div><div class=\"line\" data-l=\"3\">        <span class=\"kw\">for</span> (<span class=\"kw\">int</span> j = <span class=\"num num2\">0</span>; j &lt; n - i - <span class=\"num num2\">1</span>; j++) {</div><div class=\"line\" data-l=\"4\">            <span class=\"kw\">if</span> (arr[j] &gt; arr[j+<span class=\"num num2\">1</span>]) {</div><div class=\"line\" data-l=\"5\">                <span class=\"cm\">// std::swap writes the temp variable for you</span></div><div class=\"line\" data-l=\"6\">                <span class=\"fn\">swap</span>(arr[j], arr[j+<span class=\"num num2\">1</span>]);</div><div class=\"line\" data-l=\"6\">                swapped = <span class=\"kw\">true</span>;</div><div class=\"line\" data-l=\"7\">            }</div><div class=\"line\" data-l=\"8\">        }</div><div class=\"line\" data-l=\"11\">        <span class=\"kw\">if</span> (!swapped) <span class=\"kw\">break</span>;  <span class=\"cm\">// a clean pass means sorted</span></div><div class=\"line\" data-l=\"9\">    }</div><div class=\"line\" data-l=\"10\">}</div>"
